using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Collections.Generic;
using System.Linq;
using AuroraProxy;

class NetworkTests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);Console.WriteLine("PASS: "+name);count++;}
 static void Reject(Action action,string name){try{action();}catch(ArgumentException){Check(true,name);return;}Check(false,name);}
 const string Yaml="proxies: []\nproxy-groups:\n  - name: Direct\n    type: select\n    proxies: [DIRECT]\nrules:\n  - MATCH,DIRECT\n";
 static string Http(IPAddress address,int port,string credentials){using(var client=new TcpClient(AddressFamily.InterNetwork)){client.ReceiveTimeout=3000;client.SendTimeout=3000;client.Connect(address,port);var stream=client.GetStream();string request="GET http://127.0.0.1:28785/ok HTTP/1.1\r\nHost: 127.0.0.1:28785\r\nConnection: close\r\n"+(credentials==null?"":"Proxy-Authorization: Basic "+Convert.ToBase64String(Encoding.ASCII.GetBytes(credentials))+"\r\n")+"\r\n";byte[] bytes=Encoding.ASCII.GetBytes(request);stream.Write(bytes,0,bytes.Length);using(var reader=new StreamReader(stream))return reader.ReadToEnd();}}
 static int Read(NetworkStream stream){int value=stream.ReadByte();if(value<0)throw new IOException("Unexpected socket EOF");return value;}
 static bool Socks(IPAddress ip,int port,string user,string password){using(var c=new TcpClient(AddressFamily.InterNetwork)){c.ReceiveTimeout=3000;c.Connect(ip,port);var s=c.GetStream();s.Write(new byte[]{5,2,0,2},0,4);Check(Read(s)==5,"SOCKS5 greeting version");int method=Read(s);if(method==0)return true;Check(method==2,"LAN SOCKS5 requests user/password authentication");byte[] u=Encoding.ASCII.GetBytes(user),p=Encoding.ASCII.GetBytes(password);var packet=new List<byte>();packet.Add(1);packet.Add((byte)u.Length);packet.AddRange(u);packet.Add((byte)p.Length);packet.AddRange(p);s.Write(packet.ToArray(),0,packet.Count);return Read(s)==1&&Read(s)==0;}}
 static TcpClient Hold(int proxyPort){var c=new TcpClient();c.ReceiveTimeout=3000;c.Connect(IPAddress.Loopback,proxyPort);var request=Encoding.ASCII.GetBytes("GET http://127.0.0.1:28784/hold HTTP/1.1\r\nHost: 127.0.0.1:28784\r\n\r\n");c.GetStream().Write(request,0,request.Length);return c;}
 static List<ConnectionInfo> Connections(Engine e,int min){for(int i=0;i<50;i++){var rows=ConnectionInfo.Parse(e.Api("GET","/connections",null)).Where(x=>x.Target.EndsWith(":28784")).ToList();if(rows.Count>=min)return rows;Thread.Sleep(30);}throw new Exception("Held connection did not appear in controller");}
 static int Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"aurora-network-"+Guid.NewGuid().ToString("N"));Engine engine=null;HttpListener origin=null;TcpListener hold=null;
  try{
   var legacyRoot=Path.Combine(root,"legacy");Directory.CreateDirectory(legacyRoot);File.WriteAllText(Path.Combine(legacyRoot,"settings.json"),"{\"Profiles\":[],\"Port\":7890,\"ApiPort\":19090,\"Mode\":\"rule\"}");var legacy=new Store(legacyRoot);Check(!legacy.State.AllowLan&&legacy.State.LanAuthentication&&legacy.State.LanPassword.Length>=8&&!legacy.State.StartWithWindows,"legacy settings default to LAN off, authentication on and startup off");
   var store=new Store(root);store.State.CorePath=Path.GetFullPath(args[0]);store.State.Port=28786;store.State.ApiPort=29086;store.State.AllowLan=true;store.State.LanUser="test_user";store.State.LanPassword="aB7\"\\cD!xy";var profile=new Subscription(){Name="LAN test"};store.State.Profiles.Add(profile);store.State.Active=profile.Id;Store.Atomic(store.ProfilePath(profile),Yaml);store.Save();var reloaded=new Store(root);Check(reloaded.State.AllowLan&&reloaded.State.LanPassword==store.State.LanPassword,"LAN settings and escaped password persist without loss");
   Reject(delegate{Config.ValidateLan(true,true,"bad:user","long-enough");},"invalid shared username rejected");Reject(delegate{Config.ValidateLan(true,true,"aurora","short");},"short password rejected");Reject(delegate{Config.ValidateLan(true,true,"aurora","long-password\n");},"newline in password rejected");Reject(delegate{Config.ValidateLan(true,true,"aurora","long:password");},"colon in password rejected");
   string runtime=Config.Build("authentication: ['injected:password']\nskip-auth-prefixes: [0.0.0.0/0]\nlan-allowed-ips: [0.0.0.0/0]\nlan-disallowed-ips: [127.0.0.0/8]\n"+Yaml,store.State,"api-token");Check(runtime.Contains("allow-lan: true")&&runtime.Contains("bind-address: 0.0.0.0")&&!runtime.Contains("injected")&&!runtime.Contains("0.0.0.0/0"),"app-owned LAN access and authentication override subscription fields");Check(runtime.Contains("external-controller: 127.0.0.1:29086")&&runtime.Contains("skip-auth-prefixes: [127.0.0.0/8, '::1/128']"),"LAN sharing keeps controller private and exempts only loopback authentication");
   Check(NetworkInfo.PrivateIPv4(IPAddress.Parse("172.16.1.2"))&&!NetworkInfo.PrivateIPv4(IPAddress.Parse("172.32.1.2"))&&!NetworkInfo.PrivateIPv4(IPAddress.Parse("8.8.8.8")),"LAN address classification excludes public and out-of-range addresses");Check(Startup.Command(@"C:\Apps with spaces\AuroraProxy.exe")=="\"C:\\Apps with spaces\\AuroraProxy.exe\" --tray","startup command quotes paths and requests tray launch");Reject(delegate{Startup.Command("bad\"path");},"invalid startup path rejected");
   string help=NetworkInfo.Instructions("192.168.1.10",store.State,true);Check(help.Contains("192.168.1.10")&&help.Contains("28786")&&!help.Contains(store.State.LanPassword),"connection instructions contain address and port without copying the password");
   engine=new Engine(store);engine.Validate(runtime);Check(true,"official core validates LAN policy and quoted credentials");engine.Start(profile);
   origin=new HttpListener();origin.Prefixes.Add("http://127.0.0.1:28785/");origin.Start();var originThread=new Thread(delegate(){try{while(true){var ctx=origin.GetContext();byte[] body=Encoding.ASCII.GetBytes("LAN-OK");ctx.Response.ContentLength64=body.Length;ctx.Response.OutputStream.Write(body,0,body.Length);ctx.Response.Close();}}catch{}});originThread.IsBackground=true;originThread.Start();
   var addresses=NetworkInfo.Addresses();bool isolated=addresses.Count==0;IPAddress lan=isolated?IPAddress.Loopback:IPAddress.Parse(addresses[0].Address);
   var applied=engine.Api("GET","/configs",null);Check((bool)applied["allow-lan"]&&applied["bind-address"].ToString()=="0.0.0.0","official core applies LAN flag and shared IPv4 bind");
   Check(Http(IPAddress.Loopback,store.State.Port,null).Contains("LAN-OK"),"local proxy remains usable without credentials");if(isolated){Console.WriteLine("Loopback-only environment: temporarily remove loopback auth exemption for protocol authentication checks.");engine.Api("PATCH","/configs",new Dictionary<string,object>{{"skip-auth-prefixes",new string[0]}});}
   Check(Http(lan,store.State.Port,null).StartsWith("HTTP/1.1 407"),"HTTP requests without credentials receive 407");Check(Http(lan,store.State.Port,"test_user:wrong-password").StartsWith("HTTP/1.1 403"),"HTTP rejects incorrect credentials with 403");Check(Http(lan,store.State.Port,store.State.LanUser+":"+store.State.LanPassword).Contains("LAN-OK"),"HTTP accepts configured credentials and reaches real origin");Check(Socks(lan,store.State.Port,store.State.LanUser,store.State.LanPassword),"SOCKS5 accepts configured credentials");Check(!Socks(lan,store.State.Port,store.State.LanUser,"wrong-password"),"SOCKS5 rejects incorrect credentials");
   if(isolated)engine.Api("PATCH","/configs",new Dictionary<string,object>{{"skip-auth-prefixes",new string[]{"127.0.0.0/8","::1/128"}}});
   hold=new TcpListener(IPAddress.Loopback,28784);hold.Start();using(var first=Hold(store.State.Port)){using(var accepted=hold.AcceptTcpClient()){var rows=Connections(engine,1);Check(rows[0].Source.StartsWith("127.0.0.1:")&&rows[0].Protocol.Contains("tcp"),"real connection metadata identifies source and protocol");engine.Api("DELETE","/connections/"+Uri.EscapeDataString(rows[0].Id),null);Thread.Sleep(80);Check(!ConnectionInfo.Parse(engine.Api("GET","/connections",null)).Any(x=>x.Id==rows[0].Id),"individual connection closes through authenticated controller");}}
   using(var first=Hold(store.State.Port))using(var second=Hold(store.State.Port))using(var a=hold.AcceptTcpClient())using(var b=hold.AcceptTcpClient()){Connections(engine,2);engine.Api("DELETE","/connections",null);Thread.Sleep(80);Check(!ConnectionInfo.Parse(engine.Api("GET","/connections",null)).Any(x=>x.Target.EndsWith(":28784")),"all held connections close through authenticated controller");}
   engine.Stop();store.State.LanAuthentication=false;engine.Start(profile);Check(Http(lan,store.State.Port,null).Contains("LAN-OK"),"explicit no-auth sharing mode is usable");engine.Stop();store.State.AllowLan=false;engine.Start(profile);bool localOnly;if(isolated){var config=engine.Api("GET","/configs",null);localOnly=!(bool)config["allow-lan"]&&config["bind-address"].ToString()=="127.0.0.1";}else{bool reachable=false;try{using(var c=new TcpClient()){c.Connect(lan,store.State.Port);reachable=true;}}catch(SocketException){}localOnly=!reachable;}Check(localOnly&&Http(IPAddress.Loopback,store.State.Port,null).Contains("LAN-OK"),"turning sharing off applies local-only binding while preserving local proxy");
   Console.WriteLine("Completed "+count+" network checks.");return 0;
  }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(engine!=null)engine.Dispose();if(origin!=null)origin.Close();if(hold!=null)hold.Stop();if(Directory.Exists(root))Directory.Delete(root,true);}
 }
}
